/**
 * Client-side GATE scoring when the live /api/mcq/gate endpoint is unavailable (static hosting).
 * Uses public/data/gate-score-bundle.json generated by npm run sync:mock-offline.
 */
(function () {
  "use strict";

  var bundleCache = null;
  var bundlePromise = null;

  function loadBundle() {
    if (bundleCache) return Promise.resolve(bundleCache);
    if (bundlePromise) return bundlePromise;
    bundlePromise = fetch("/data/gate-score-bundle.json", { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("Offline scoring data is missing.");
        return r.json();
      })
      .then(function (data) {
        bundleCache = data && data.papers ? data : { papers: {} };
        return bundleCache;
      });
    return bundlePromise;
  }

  function optionLetter(i) {
    return i >= 0 && i < 26 ? String.fromCharCode(65 + i) : String(i + 1);
  }

  function solutionForQuestion(q, correctIndex, authored) {
    if (authored && authored.explanation) {
      return {
        explanation: String(authored.explanation),
        optionExplanations: Array.isArray(authored.options)
          ? authored.options.map(String)
          : [],
        understanding: authored.understanding ? String(authored.understanding) : "",
        solutionText: authored.solutionText ? String(authored.solutionText) : "",
        keyConcept: authored.keyConcept ? String(authored.keyConcept) : "",
        correctAnswerLine: "",
        solutionSource: "static"
      };
    }
    var opts = q.options || [];
    var ci = correctIndex >= 0 ? correctIndex : 0;
    var correctText = opts[ci] != null ? String(opts[ci]) : "—";
    return {
      explanation:
        "The correct option is " +
        optionLetter(ci) +
        ". Compare your response with the keyed answer for this mock question.",
      optionExplanations: opts.map(function (text, i) {
        var letter = optionLetter(i);
        return i === ci
          ? letter + ". " + text + " — Correct."
          : letter + ". " + text + " — Incorrect.";
      }),
      understanding: "",
      solutionText: "",
      keyConcept: "",
      correctAnswerLine: "(" + (ci + 1) + ") " + correctText,
      solutionSource: "fallback"
    };
  }

  /**
   * @param {string} slug
   * @param {Record<string, number>} responses
   * @param {{ title?: string, sections: Array }} paper
   */
  function scoreOffline(slug, responses, paper) {
    return loadBundle().then(function (bundle) {
      var entry = bundle.papers && bundle.papers[slug];
      if (!entry || !entry.answers) {
        throw new Error("Offline scoring is not available for this paper. Run npm run sync:mock-offline on the server.");
      }

      var answerKey = entry.answers;
      var solutions = entry.solutions || {};
      var allQuestions = [];
      (paper.sections || []).forEach(function (sec) {
        (sec.questions || []).forEach(function (q) {
          allQuestions.push(q);
        });
      });

      var score = 0;
      var maxMarks = 0;
      var correct = 0;
      var wrong = 0;
      var unattempted = 0;
      var sectionMap = {};
      var review = [];

      allQuestions.forEach(function (q) {
        maxMarks += q.marks || 0;
        var ans = responses[q.id];
        var expected = answerKey[q.id];
        var status = "skipped";
        var selected = -1;
        var marksAwarded = 0;

        if (ans !== undefined && ans !== null && ans >= 0) {
          selected = ans;
          if (expected != null && ans === expected) {
            status = "correct";
            score += q.marks || 0;
            marksAwarded = q.marks || 0;
            correct += 1;
          } else {
            status = "incorrect";
            score -= q.negativeMarks || 0;
            marksAwarded = -(q.negativeMarks || 0);
            wrong += 1;
          }
        } else {
          unattempted += 1;
        }

        var secKey = q.sectionKey || "default";
        if (!sectionMap[secKey]) {
          sectionMap[secKey] = {
            key: secKey,
            label: q.sectionLabel || secKey,
            total: 0,
            correct: 0,
            wrong: 0,
            skipped: 0
          };
        }
        var sec = sectionMap[secKey];
        sec.total += 1;
        if (status === "correct") sec.correct += 1;
        else if (status === "incorrect") sec.wrong += 1;
        else sec.skipped += 1;

        var detail = solutionForQuestion(q, expected, solutions[q.id]);
        review.push({
          id: q.id,
          number: q.number,
          sectionKey: secKey,
          sectionLabel: q.sectionLabel || secKey,
          text: q.text,
          options: q.options || [],
          status: status,
          selected: selected,
          correctIndex: expected != null ? expected : -1,
          correctOption: expected != null && expected >= 0 ? optionLetter(expected) : "",
          marks: q.marks,
          negativeMarks: q.negativeMarks,
          marksAwarded: marksAwarded,
          explanation: detail.explanation,
          optionExplanations: detail.optionExplanations,
          understanding: detail.understanding,
          solutionText: detail.solutionText,
          keyConcept: detail.keyConcept,
          correctAnswerLine: detail.correctAnswerLine,
          solutionSource: detail.solutionSource
        });
      });

      var sections = Object.keys(sectionMap).map(function (k) {
        var s = sectionMap[k];
        return {
          key: s.key,
          label: s.label,
          total: s.total,
          correct: s.correct,
          wrong: s.wrong,
          skipped: s.skipped,
          accuracy: s.total > 0 ? Math.round((s.correct / s.total) * 100) : 0
        };
      });

      return {
        ok: true,
        offlineScore: true,
        reviewToken: "",
        year: entry.year,
        title: paper.title || entry.title,
        score: Math.round(score * 100) / 100,
        maxMarks: maxMarks,
        correct: correct,
        wrong: wrong,
        unattempted: unattempted,
        total: allQuestions.length,
        attempted: correct + wrong,
        percentage: maxMarks > 0 ? Math.round((score / maxMarks) * 1000) / 10 : 0,
        sections: sections,
        review: review
      };
    });
  }

  window.GateExamOfflineScore = {
    loadBundle: loadBundle,
    scoreOffline: scoreOffline
  };
})();
